import marshal, zlib, base64

encrypted_payload = ""

try:
    decoded_data = base64.b64decode(encrypted_payload.encode('utf-8'))
    decompressed_data = zlib.decompress(decoded_data)
    unmarshaled_code = marshal.loads(decompressed_data)
    exec(unmarshaled_code)
except Exception as e:
    print("Error:", e)
